import droppedPosts from './lib/dropped-posts.json' with { type: 'json' };

const BALI = '/bali-200-hour-teacher-training';

/** @type {import('next').NextConfig} */
const nextConfig = {
  reactStrictMode: true,
  // Pre-sized WebP files are generated by scripts/build-images.mjs, so Vercel image optimisation is not used
  images: { unoptimized: true },
  async headers() {
    return [
      {
        // Every file in public/images has a content hash in its name, so it never changes in place.
        // Without this, files in public/ are served with max-age=0 and revalidated on every visit.
        source: '/images/:file*',
        headers: [{ key: 'Cache-Control', value: 'public, max-age=31536000, immutable' }],
      },
      {
        // Browser icons rarely change; a week of caching avoids a revalidation request on every visit
        source: '/:icon(favicon.ico|icon.png|apple-icon.png)',
        headers: [{ key: 'Cache-Control', value: 'public, max-age=604800, stale-while-revalidate=86400' }],
      },
    ];
  },
  async redirects() {
    return [
      // Legacy Wix routes mapped onto the compact route structure
      { source: '/ttc-online-recording', destination: '/online-recording', permanent: true },
      { source: '/ttc-online-live-zoom', destination: '/indonesia#live-zoom', permanent: true },
      { source: '/ttc-offline-bahasa-indonesia', destination: '/indonesia', permanent: true },
      { source: '/review', destination: '/#graduates', permanent: true },
      { source: '/book-online', destination: BALI, permanent: true },
      { source: '/service-page/:path*', destination: BALI, permanent: true },
      { source: '/booking-calendar/:path*', destination: BALI, permanent: true },
      { source: '/plans-pricing', destination: BALI, permanent: true },
      { source: '/blog/categories/:path*', destination: '/blog', permanent: true },
      { source: '/blank', destination: '/', permanent: true },
      { source: '/cart-page', destination: '/', permanent: true },
      { source: '/account/:path*', destination: '/', permanent: true },
      { source: '/search', destination: '/', permanent: true },
      ...droppedPosts.map((slug) => ({ source: `/post/${slug}`, destination: '/blog', permanent: true })),
    ];
  },
};

export default nextConfig;
